record.field:
# Procedure for optimized service account resolution and security verification
#
# Split into two halves, 2026-09-13 (Bruce's own direct instruction: "Change the initialization
# software to load the service user-IDs into a hash-table at start-up"): zero_sudo_resolve_
# service_xmlid() is the pure ir_model_data lookup -- genuinely immutable once a noupdate="1"
# data record installs, safe to cache in-process -- and zero_sudo_verify_service_uid() is the
# LIVE safety verdict (active / is_service_account / no privilege-escalation), which must never
# be cached since any of those three can change at runtime (an admin disabling a compromised
# account, a group grant changing). zero_sudo_get_service_uid() itself is kept as a thin
# combination of both, byte-for-byte behaviorally identical to its old single-function form, so
# every existing direct SQL caller (and every existing test asserting its exact exception
# messages) keeps working unchanged. security_utils.py's own _get_service_uid() is what actually
# calls the two halves separately to skip the ir_model_data resolution on a cache hit -- see its
# own docstring for the Python-side half of this story.
sql_resolve_xmlid = """
CREATE OR REPLACE FUNCTION zero_sudo_resolve_service_xmlid(p_xml_id TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_module TEXT;
    v_name TEXT;
    v_uid INTEGER;
BEGIN
    v_module := split_part(p_xml_id, '.', 1);
    v_name := split_part(p_xml_id, '.', 2);

    SELECT res_id INTO v_uid
    FROM ir_model_data
    WHERE module = v_module AND name = v_name AND model = 'res.users';

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Security Alert: Service Account % not found.', p_xml_id;
    END IF;

    RETURN v_uid;
END;
$$ LANGUAGE plpgsql;
"""

sql_verify_uid = """
CREATE OR REPLACE FUNCTION zero_sudo_verify_service_uid(p_uid INTEGER, p_xml_id TEXT)
RETURNS VOID AS $$
DECLARE
    v_active BOOLEAN;
    v_is_svc BOOLEAN;
    v_has_privilege_escalation BOOLEAN;
BEGIN
    SELECT active, is_service_account INTO v_active, v_is_svc
    FROM res_users WHERE id = p_uid;

    IF v_active IS NOT TRUE THEN
        RAISE EXCEPTION 'Security Alert: Service Account % is disabled.', p_xml_id;
    END IF;

    IF v_is_svc IS NOT TRUE THEN
        RAISE EXCEPTION 'Security Alert: % is a human user, not a Service Account.', p_xml_id;
    END IF;

    -- Bug-hunt fix: checking res_groups_users_rel alone only sees DIRECT
    -- group membership. Odoo's own group hierarchy also grants a user
    -- everything a directly-held group's own implied_ids chain reaches
    -- (res_groups_implied_rel: gid -> hid means "membership in gid implies
    -- membership in hid"), and Odoo's own has_group()/all_group_ids checks
    -- that full transitive closure, not just direct rows -- confirmed by
    -- reading odoo/addons/base/models/res_users.py's own _has_group(),
    -- which checks all_group_ids (computed from group_ids.all_implied_ids),
    -- never a raw membership-table query. A service account holding
    -- base.group_system/base.group_erp_manager only via an IMPLIED chain
    -- (member of some other group X whose own implied_ids reaches one of
    -- these, directly or through several hops) previously passed this
    -- check silently, defeating the entire Zero-Sudo mandate this function
    -- exists to enforce. The recursive CTE below walks that same implied
    -- closure from the user's directly-held groups before checking for
    -- group_system/group_erp_manager anywhere in it.
    SELECT EXISTS (
        SELECT 1
        FROM (
            WITH RECURSIVE effective_groups(gid) AS (
                SELECT rel.gid FROM res_groups_users_rel rel WHERE rel.uid = p_uid
                UNION
                SELECT imp.hid
                FROM res_groups_implied_rel imp
                JOIN effective_groups eg ON imp.gid = eg.gid
            )
            SELECT gid FROM effective_groups
        ) eg
        JOIN ir_model_data imd ON imd.res_id = eg.gid AND imd.model = 'res.groups'
        WHERE imd.module = 'base' AND imd.name IN ('group_system', 'group_erp_manager')
    ) INTO v_has_privilege_escalation;

    IF v_has_privilege_escalation THEN
        RAISE EXCEPTION 'Security Alert: Service Account % violates the Zero-Sudo mandate by possessing global administrative groups.', p_xml_id;
    END IF;
END;
$$ LANGUAGE plpgsql;
"""

sql_get_uid = """
CREATE OR REPLACE FUNCTION zero_sudo_get_service_uid(p_xml_id TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_uid INTEGER;
BEGIN
    v_uid := zero_sudo_resolve_service_xmlid(p_xml_id);
    PERFORM zero_sudo_verify_service_uid(v_uid, p_xml_id);
    RETURN v_uid;
END;
$$ LANGUAGE plpgsql;
"""

# Function for high-performance atomic KV storage
sql_set_kv = """
CREATE OR REPLACE FUNCTION zero_sudo_set_kv(p_key TEXT, p_value TEXT)
RETURNS VOID AS $$
BEGIN
    INSERT INTO zero_sudo_kv (key, value)
    VALUES (p_key, p_value)
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
END;
$$ LANGUAGE plpgsql;
"""

env.cr.execute(sql_resolve_xmlid)
env.cr.execute(sql_verify_uid)
env.cr.execute(sql_get_uid)
env.cr.execute(sql_set_kv)
